import Model from 'flarum/common/Model';
export default class HeadItem extends Model {
  description() {
    return Model.attribute('description').call(this);
  }
  header() {
    return Model.attribute('header').call(this);
  }
  active() {
    return Model.attribute('active').call(this);
  }
}
flarum.reg.add('ianm-html-head', 'admin/model/HeadItem', HeadItem);